// The water's procedural textures as ONE DataArrayTexture (layer 0 = foam, 1 = noise, 2 = caustic net). The data is
// generated by texbake.ts — in the bake worker (bake.worker.ts) during the load, or here as a fallback.
import * as THREE from "three";
import { waterTexData } from "./texbake";
import { flag } from "../../flags";

/** layer 0 = foam, layer 1 = noise, layer 2 = caustic net (one sampler unit for all) */
export interface WaterTextures { array: THREE.DataArrayTexture; size: number; fill(data: Uint8Array): void }

/** empty = allocate only (the worker fills it); otherwise generate the data now on this thread */
export function makeWaterTextures(size = 512, empty = false): WaterTextures {
  const arr = empty ? new Uint8Array(size * size * 4 * 3).fill(128) : waterTexData(size);
  const t = new THREE.DataArrayTexture(arr, size, size, 3);
  t.format = THREE.RGBAFormat; t.type = THREE.UnsignedByteType;
  t.wrapS = t.wrapT = THREE.RepeatWrapping;
  t.minFilter = THREE.LinearMipmapLinearFilter; t.magFilter = THREE.LinearFilter;
  t.generateMipmaps = true; t.anisotropy = flag("waniso") || 4; t.colorSpace = THREE.NoColorSpace; t.needsUpdate = true;
  return {
    array: t, size,
    fill(data: Uint8Array) { (t.image as { data: Uint8Array }).data = data; t.needsUpdate = true; },
  };
}
